-- V2.9H SQLite baseline schema for new local/dev databases.
-- This file contains schema only; it does not seed business data.

CREATE TABLE IF NOT EXISTS "activity_registration" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "userId" varchar(100) NOT NULL, "activityId" integer NOT NULL, "status" varchar(50) NOT NULL DEFAULT ('REGISTERED'), "createdAt" datetime NOT NULL DEFAULT (datetime('now')), checkedInAt datetime NULL, checkedInByUserId varchar(50) NULL, checkinSource varchar(30) NULL, CONSTRAINT "FK_ac95c2995c601625a9ad09efcd1" FOREIGN KEY ("activityId") REFERENCES "activity" ("id") ON DELETE NO ACTION ON UPDATE NO ACTION);
CREATE UNIQUE INDEX IF NOT EXISTS uniq_activity_registration_user_activity ON activity_registration (userId, activityId);
CREATE TABLE IF NOT EXISTS "activity_refund" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "orderId" integer NOT NULL, "userId" varchar(100), "activityId" integer, "amount" decimal(10,2) NOT NULL DEFAULT (0), "reason" varchar(500), "status" varchar(20) NOT NULL DEFAULT ('SUCCESS'), "createdAt" datetime NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS "user_tag" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "userId" varchar(100) NOT NULL, "tag" varchar(50) NOT NULL, "createdAt" datetime NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS "user_note" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "userId" varchar(100) NOT NULL, "note" text NOT NULL, "createdAt" datetime NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS "user_profile" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "userId" varchar(100) NOT NULL, "birthYearMonth" varchar(7), "registeredAt" datetime, "lastLoginAt" datetime, "createdAt" datetime NOT NULL DEFAULT (datetime('now')), CONSTRAINT "UQ_51cb79b5555effaf7d69ba1cff9" UNIQUE ("userId"));
CREATE TABLE IF NOT EXISTS "user_invite_record" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "inviterUserId" varchar(100) NOT NULL, "inviteeUserId" varchar(100) NOT NULL, "createdAt" datetime NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS "activity_invite_record" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "activityId" integer NOT NULL, "inviterUserId" varchar(100) NOT NULL, "inviteeUserId" varchar(100) NOT NULL, "registrationId" integer, "createdAt" datetime NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS "activity_registration_info" ("id" varchar(50) PRIMARY KEY NOT NULL, "activityId" integer NOT NULL, "registrationId" integer, "userId" varchar(100) NOT NULL, "realName" varchar(50), "phone" varchar(30), "idCardNo" varchar(50), "departureCity" varchar(50), "transportPreference" varchar(50), "roomPreference" varchar(100), "confirmedAt" datetime, "createdAt" datetime NOT NULL DEFAULT (datetime('now')), "updatedAt" datetime NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS "certificate_template" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "name" varchar(100) NOT NULL, "description" varchar(300), "imageUrl" varchar(500) NOT NULL, "isDefault" boolean NOT NULL DEFAULT (0), "enabled" boolean NOT NULL DEFAULT (1), "fieldConfig" text, "createdAt" datetime NOT NULL DEFAULT (datetime('now')), "updatedAt" datetime NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS "user" ("id" varchar(50) PRIMARY KEY NOT NULL, "wechatAppId" varchar(100) NOT NULL, "openid" varchar(200) NOT NULL, "unionid" varchar(200), "phone" varchar(50), "nickname" varchar(100), "avatarUrl" varchar(500), "gender" varchar(20), "birthday" varchar(10), "birthYearMonth" varchar(7), "identityType" varchar(50), "isMember" boolean NOT NULL DEFAULT (0), "isLifetimeMember" boolean NOT NULL DEFAULT (0), "registeredAt" datetime NOT NULL DEFAULT (datetime('now')), "lastLoginAt" datetime, "status" varchar(20) NOT NULL DEFAULT ('ACTIVE'), "createdAt" datetime NOT NULL DEFAULT (datetime('now')), "updatedAt" datetime NOT NULL DEFAULT (datetime('now')), "intro" varchar(200));
CREATE UNIQUE INDEX IF NOT EXISTS uq_user_wechat_app_openid ON "user" (wechatAppId, openid);
CREATE TABLE IF NOT EXISTS "user_invoice_profile" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "userId" varchar(100) NOT NULL, "invoiceType" varchar(20) NOT NULL DEFAULT ('PERSONAL'), "invoiceTitle" varchar(200) NOT NULL, "taxNumber" varchar(50), "companyAddress" varchar(200), "companyPhone" varchar(50), "bankName" varchar(120), "bankAccount" varchar(80), "email" varchar(120), "remark" varchar(300), "createdAt" datetime NOT NULL DEFAULT (datetime('now')), "updatedAt" datetime NOT NULL DEFAULT (datetime('now')), CONSTRAINT "UQ_71e652c42c23ae626c0aaf192c6" UNIQUE ("userId"));
CREATE TABLE IF NOT EXISTS "user_registration_profile" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "userId" varchar(50) NOT NULL, "realName" varchar(50), "phone" varchar(30), "idCardNo" varchar(50), "departureCity" varchar(50), "transportPreference" varchar(50), "roomPreference" varchar(100), "createdAt" datetime NOT NULL DEFAULT (datetime('now')), "updatedAt" datetime NOT NULL DEFAULT (datetime('now')), CONSTRAINT "UQ_7831d0319e1315eb9400849adef" UNIQUE ("userId"));
CREATE TABLE IF NOT EXISTS "activity_invoice" ("id" integer PRIMARY KEY AUTOINCREMENT NOT NULL, "orderId" integer NOT NULL, "userId" varchar(100), "activityId" integer, "title" varchar(200) NOT NULL, "taxNo" varchar(50), "amount" decimal(10,2) NOT NULL DEFAULT (0), "status" varchar(20) NOT NULL DEFAULT ('REQUESTED'), "createdAt" datetime NOT NULL DEFAULT (datetime('now')), "issuedAt" datetime, "invoiceType" varchar(20), "companyAddress" varchar(200), "companyPhone" varchar(50), "bankName" varchar(120), "bankAccount" varchar(80), "email" varchar(120), "remark" varchar(300));
CREATE TABLE IF NOT EXISTS operation_banner (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, imageUrl varchar(500) NOT NULL, title varchar(100) NOT NULL, description varchar(240), sortOrder integer NOT NULL DEFAULT 0, status varchar(20) NOT NULL DEFAULT ('ACTIVE'), startAt datetime, endAt datetime, jumpType varchar(20) NOT NULL DEFAULT ('NONE'), jumpValue varchar(120), createdAt datetime NOT NULL DEFAULT (datetime('now')), updatedAt datetime NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_operation_banner_active_window ON operation_banner (status, sortOrder, startAt, endAt);
CREATE INDEX IF NOT EXISTS idx_operation_banner_jump ON operation_banner (jumpType, jumpValue);
CREATE TABLE IF NOT EXISTS "activity_order" (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, userId varchar(100), activityId integer, registrationId integer NOT NULL, amount decimal(10,2) NOT NULL DEFAULT 0, refundedAmount decimal(10,2) NOT NULL DEFAULT 0, refundCount integer NOT NULL DEFAULT 0, status varchar(30) NOT NULL DEFAULT ('PENDING'), payType varchar(20) NOT NULL DEFAULT ('FULL'), createdAt datetime NOT NULL DEFAULT (datetime('now')), paidAt datetime, refundedAt datetime, userTypeAtOrder varchar(50), priceSource varchar(50), fullAmount decimal(10,2), orderPrepayAmount decimal(10,2), orderPostpayAmount decimal(10,2), pricingSnapshot text, postpayStatus varchar(30) NOT NULL DEFAULT ('NONE'), postpayPaidAt datetime, postpayReminderCount integer NOT NULL DEFAULT 0, lastPostpayReminderAt datetime, postpayWaivedAt datetime, postpayWaiveReason text, CONSTRAINT UQ_activity_order_registration UNIQUE (registrationId), CONSTRAINT FK_activity_order_registration FOREIGN KEY (registrationId) REFERENCES activity_registration (id) ON DELETE NO ACTION ON UPDATE NO ACTION);
CREATE TABLE IF NOT EXISTS payment_transaction (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, orderId integer NOT NULL, registrationId integer NOT NULL, userId varchar(100) NOT NULL, activityId integer NOT NULL, tradeType varchar(20) NOT NULL, paymentProvider varchar(30) NOT NULL DEFAULT ('WECHAT'), merchantOrderNo varchar(64) NOT NULL, providerTransactionNo varchar(128), amount decimal(10,2) NOT NULL DEFAULT 0, amountCents integer NOT NULL, status varchar(30) NOT NULL DEFAULT ('INIT'), prepayId varchar(128), paidAt datetime, notifyAt datetime, createdAt datetime NOT NULL DEFAULT (datetime('now')), updatedAt datetime NOT NULL DEFAULT (datetime('now')), CONSTRAINT uq_payment_transaction_merchant_order_no UNIQUE (merchantOrderNo), CONSTRAINT uq_payment_transaction_provider_transaction_no UNIQUE (providerTransactionNo));
CREATE INDEX IF NOT EXISTS idx_payment_transaction_order ON payment_transaction (orderId);
CREATE INDEX IF NOT EXISTS idx_payment_transaction_user ON payment_transaction (userId);
CREATE INDEX IF NOT EXISTS idx_payment_transaction_activity ON payment_transaction (activityId);
CREATE INDEX IF NOT EXISTS idx_payment_transaction_status ON payment_transaction (status);
CREATE INDEX IF NOT EXISTS idx_payment_transaction_trade_type ON payment_transaction (tradeType);
CREATE UNIQUE INDEX IF NOT EXISTS uniq_payment_transaction_order_trade_type ON payment_transaction (orderId, tradeType);
CREATE TABLE IF NOT EXISTS refund_transaction (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, orderId integer NOT NULL, paymentTransactionId integer NOT NULL, activityRefundId integer, refundProvider varchar(30) NOT NULL DEFAULT ('WECHAT'), merchantRefundNo varchar(64) NOT NULL, providerRefundNo varchar(128), amount decimal(10,2) NOT NULL DEFAULT 0, amountCents integer NOT NULL, status varchar(30) NOT NULL DEFAULT ('INIT'), reason varchar(500), failureReason text, requestedAt datetime, successAt datetime, createdAt datetime NOT NULL DEFAULT (datetime('now')), updatedAt datetime NOT NULL DEFAULT (datetime('now')), CONSTRAINT uq_refund_transaction_merchant_refund_no UNIQUE (merchantRefundNo), CONSTRAINT uq_refund_transaction_provider_refund_no UNIQUE (providerRefundNo));
CREATE INDEX IF NOT EXISTS idx_refund_transaction_order ON refund_transaction (orderId);
CREATE INDEX IF NOT EXISTS idx_refund_transaction_payment ON refund_transaction (paymentTransactionId);
CREATE INDEX IF NOT EXISTS idx_refund_transaction_status ON refund_transaction (status);
CREATE TABLE IF NOT EXISTS activity_category (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, name varchar(80) NOT NULL, code varchar(50) NOT NULL, description text, sortOrder integer NOT NULL DEFAULT 0, status varchar(20) NOT NULL DEFAULT ('ACTIVE'), createdAt datetime NOT NULL DEFAULT (datetime('now')), updatedAt datetime NOT NULL DEFAULT (datetime('now')), CONSTRAINT uq_activity_category_code UNIQUE (code));
CREATE INDEX IF NOT EXISTS idx_activity_category_status_sort ON activity_category (status, sortOrder);
CREATE TABLE IF NOT EXISTS activity_series (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, name varchar(80) NOT NULL, code varchar(50) NOT NULL, coverImage varchar(500), shortDescription varchar(120), description text, externalUrl varchar(500), sortOrder integer NOT NULL DEFAULT 0, status varchar(20) NOT NULL DEFAULT ('ACTIVE'), createdAt datetime NOT NULL DEFAULT (datetime('now')), updatedAt datetime NOT NULL DEFAULT (datetime('now')));
CREATE UNIQUE INDEX IF NOT EXISTS uq_activity_series_code ON activity_series (code);
CREATE INDEX IF NOT EXISTS idx_activity_series_status_sort ON activity_series (status, sortOrder);
CREATE TABLE IF NOT EXISTS activity_follow (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, userId varchar(100) NOT NULL, activityId integer NOT NULL, followedAt datetime NOT NULL, unfollowedAt datetime, convertedAt datetime, createdAt datetime NOT NULL DEFAULT (datetime('now')), updatedAt datetime NOT NULL DEFAULT (datetime('now')));
CREATE UNIQUE INDEX IF NOT EXISTS uniq_activity_follow_user_activity ON activity_follow (userId, activityId);
CREATE INDEX IF NOT EXISTS idx_activity_follow_activity_current ON activity_follow (activityId, unfollowedAt);
CREATE TABLE IF NOT EXISTS "activity" (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, title varchar(200) NOT NULL, categoryId integer, slogan varchar(100), province varchar(50), description text, location varchar(300), city varchar(100), startTime datetime, endTime datetime, registrationStartTime datetime, registrationEndTime datetime, capacity integer NOT NULL DEFAULT 0, coverImage varchar(500), price integer NOT NULL DEFAULT 0, memberPrice integer NOT NULL DEFAULT 0, lifetimeMemberPrice integer NOT NULL DEFAULT 0, paymentMode varchar(20) NOT NULL DEFAULT ('FULL'), prepayAmount integer NOT NULL DEFAULT 0, remainingAmount integer NOT NULL DEFAULT 0, remainingPayDate datetime, status varchar(50) NOT NULL DEFAULT ('DRAFT'), requiredUserInfoFields text, groupQrType varchar(30) NOT NULL DEFAULT ('NONE'), groupQrImageUrl varchar(500), groupQrTitle varchar(100) NOT NULL DEFAULT ('加入活动群'), groupQrDescription varchar(200) NOT NULL DEFAULT ('活动通知、集合安排和现场事项将在群内同步'), memoryImages text, memoryText text, certificateTemplateId integer, imageUrls text, contentBlocks text, pricingRules text, postpayDate varchar(50), provinceName varchar(50), provinceCode varchar(20), cityName varchar(50), cityCode varchar(20), adcode varchar(20), lng float, lat float, locationName varchar(200), locationAddress varchar(500), locationLat float, locationLng float, coordinateType varchar(20) NOT NULL DEFAULT ('gcj02'), locationProvider varchar(20) NOT NULL DEFAULT ('manual'), createdAt datetime NOT NULL DEFAULT (datetime('now')), seriesId integer REFERENCES activity_series(id) ON DELETE SET NULL ON UPDATE NO ACTION, CONSTRAINT fk_activity_category FOREIGN KEY (categoryId) REFERENCES activity_category (id) ON DELETE SET NULL ON UPDATE NO ACTION);
CREATE INDEX IF NOT EXISTS idx_activity_category_id ON activity (categoryId);
CREATE INDEX IF NOT EXISTS idx_activity_series_id ON activity (seriesId);
CREATE TABLE IF NOT EXISTS tag_definition (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, name varchar(80) NOT NULL, type varchar(20) NOT NULL, description text, ruleCode varchar(80), isEnabled boolean NOT NULL DEFAULT 1, createdAt datetime NOT NULL DEFAULT (datetime('now')), updatedAt datetime NOT NULL DEFAULT (datetime('now')), CONSTRAINT uq_tag_definition_type_name UNIQUE (type, name), CONSTRAINT uq_tag_definition_rule_code UNIQUE (ruleCode));
CREATE INDEX IF NOT EXISTS idx_tag_definition_type_enabled ON tag_definition (type, isEnabled);
CREATE TABLE IF NOT EXISTS user_tag_relation (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, userId varchar(100) NOT NULL, tagId integer NOT NULL, source varchar(20) NOT NULL, assignedAt datetime NOT NULL DEFAULT (datetime('now')), assignedBy varchar(100), CONSTRAINT uq_user_tag_relation_user_tag UNIQUE (userId, tagId), CONSTRAINT fk_user_tag_relation_tag FOREIGN KEY (tagId) REFERENCES tag_definition (id) ON DELETE CASCADE ON UPDATE NO ACTION);
CREATE INDEX IF NOT EXISTS idx_user_tag_relation_user ON user_tag_relation (userId);
CREATE INDEX IF NOT EXISTS idx_user_tag_relation_tag ON user_tag_relation (tagId);
CREATE TABLE IF NOT EXISTS activity_qr (id integer PRIMARY KEY AUTOINCREMENT NOT NULL, code varchar(64) NOT NULL, status varchar(50) NOT NULL DEFAULT ('ACTIVE'), stage varchar(20) NOT NULL DEFAULT ('LEGACY'), version integer NOT NULL DEFAULT 1, expiresAt datetime, supersededAt datetime, revokedAt datetime, createdAt datetime NOT NULL DEFAULT (datetime('now')), registrationId integer NOT NULL, CONSTRAINT UQ_activity_qr_code UNIQUE (code), CONSTRAINT FK_activity_qr_registration FOREIGN KEY (registrationId) REFERENCES activity_registration (id) ON DELETE NO ACTION ON UPDATE NO ACTION);
CREATE UNIQUE INDEX IF NOT EXISTS uniq_activity_qr_registration_version ON activity_qr (registrationId, version);
CREATE INDEX IF NOT EXISTS idx_activity_qr_registration_id ON activity_qr (registrationId);
CREATE INDEX IF NOT EXISTS idx_activity_qr_registration_status ON activity_qr (registrationId, status);
